// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log lf;

    function setUp() public {
        lf = new Log();
        c = new X_WALLET(address(lf));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // A successful Put must have logged a message: first History entry
        // matches this deposit (sender == actor, Val == amount).
        bool recorded;
        try lf.History(0) returns (address sender, string memory, uint256 val, uint256) {
            recorded = (sender == actor && val == amount);
        } catch {
            recorded = false;
        }

        assertTrue(!ok || recorded);
    }
}
